import time
from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Parity (0 or 1) of each element of xs, computed in parallel with a
    thread pool. Results are in input order regardless of worker count or
    task completion order."""
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3, 4, 5]) == [0, 1, 0, 1, 0, 1]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negatives() -> None:
    assert parities([-1, -2, -3, -4]) == [1, 0, 1, 0]


def test_parities_large_matches_sequential() -> None:
    xs = list(range(-500, 1500))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_does_not_mutate_input() -> None:
    xs = [3, 4, 5]
    parities(xs)
    assert xs == [3, 4, 5]


def test_parities_repeatable() -> None:
    xs = [7, 8, 9, 10, 11, 12, 13] * 20
    first = parities(xs)
    for _ in range(5):
        assert parities(xs) == first


def test_parities_order_independent_of_completion_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    n = 16

    def slow_parity(x: int) -> int:
        # Earlier elements take longer, so they finish last.
        time.sleep(0.002 * (n - x))
        return x % 2

    monkeypatch.setattr(f"{__name__}.parity", slow_parity)
    xs = list(range(n))
    assert parities(xs) == [x % 2 for x in xs]
